    @Override public void onCreate(Bundle arguments){super.onCreate(arguments);start();}
    private void require(boolean value,String message){if(!value)throw new AssertionError(message);}
    private void ui(Runnable task){Throwable[] error={null};runOnMainSync(()->{try{task.run();}catch(Throwable failure){error[0]=failure;}});if(error[0]!=null)throw new AssertionError("UI check: "+error[0],error[0]);}
    private String js(Activity activity,String script)throws Exception{CountDownLatch done=new CountDownLatch(1);String[] result={""};ui(()->{android.view.View root=activity.getWindow().getDecorView();WebView web=findWeb(root);if(web==null){done.countDown();return;}web.evaluateJavascript(script,value->{result[0]=value;done.countDown();});});require(done.await(10,TimeUnit.SECONDS),"JavaScript timed out");return result[0];}
    private WebView findWeb(android.view.View view){if(view instanceof WebView)return (WebView)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){WebView found=findWeb(group.getChildAt(i));if(found!=null)return found;}}return null;}
    private void screenshot(String name)throws Exception{File dir=new File(getTargetContext().getFilesDir(),"qa");dir.mkdirs();Bitmap image=getUiAutomation().takeScreenshot();require(image!=null,"Screenshot unavailable");try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private int photos(android.view.View view){int count=view.getId()==R.id.story_photo&&view instanceof ImageView&&((ImageView)view).getDrawable()!=null?1:0;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)count+=photos(group.getChildAt(i));}return count;}
    private <T extends android.view.View> T find(android.view.View view,Class<T> type){if(type.isInstance(view)&&!(type==Button.class&&view instanceof CompoundButton))return type.cast(view);if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){T found=find(group.getChildAt(i),type);if(found!=null)return found;}}return null;}
    private android.view.View findId(android.view.View view,int id){if(view.getId()==id)return view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){android.view.View found=findId(group.getChildAt(i),id);if(found!=null)return found;}}return null;}
    private android.view.View widget(Activity preview,int id){android.view.View[] result={null};ui(()->{android.view.ViewGroup root=(android.view.ViewGroup)preview.getWindow().getDecorView();result[0]=hostView(root,id);});require(result[0]!=null,"Native host view missing "+id);return result[0];}
    private android.view.View hostView(android.view.View view,int id){if(view instanceof android.appwidget.AppWidgetHostView&&((android.appwidget.AppWidgetHostView)view).getAppWidgetId()==id)return view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++){android.view.View found=hostView(group.getChildAt(i),id);if(found!=null)return found;}}return null;}
    private String title(android.view.View widget){String[] text={""};ui(()->{TextView title=(TextView)findId(widget,R.id.story_title);if(title!=null)text[0]=title.getText().toString();});return text[0];}
    private void click(android.view.View widget,int id){ui(()->{android.view.View control=findId(widget,id);require(control!=null,"Widget control missing");control.performClick();});}
    private void awaitTitle(android.view.View widget,String expected)throws Exception{for(int i=0;i<30;i++){if(title(widget).equals(expected))return;Thread.sleep(100);}throw new AssertionError("Widget did not display expected article: "+title(widget));}
    private void swipe(android.graphics.Rect bounds)throws Exception{float x=bounds.centerX(),from=bounds.bottom-16,to=bounds.top+16;long time=android.os.SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(time,time,0,x,from,0);down.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);require(getUiAutomation().injectInputEvent(down,true),"Touchscreen event rejected");down.recycle();for(int step=1;step<=12;step++){android.view.MotionEvent move=android.view.MotionEvent.obtain(time,time+step*25,2,x,from+(to-from)*step/12f,0);move.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);require(getUiAutomation().injectInputEvent(move,true),"Touchscreen event rejected");move.recycle();Thread.sleep(25);}android.view.MotionEvent up=android.view.MotionEvent.obtain(time,time+325,1,x,to,0);up.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);require(getUiAutomation().injectInputEvent(up,true),"Touchscreen event rejected");up.recycle();}
